import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(n):
        try:
            i = int(next(iterator))
            j = int(next(iterator))
        except StopIteration:
            break

        depth_i = i.bit_length()
        depth_j = j.bit_length()

        dist = 0

        while i != j:
            if depth_i > depth_j:
                i //= 2
                depth_i -= 1
                dist += 1
            elif depth_j > depth_i:
                j //= 2
                depth_j -= 1
                dist += 1
            else:
                i //= 2
                j //= 2
                depth_i -= 1
                depth_j -= 1
                dist += 2

        results.append(str(dist))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    main()
